<script setup>
import { computed, ref, watch } from 'vue';
const props=defineProps({mode:{type:String,required:true},completado:{type:Boolean,default:false}});const emit=defineEmits(['hablar','practicar']);
const paso=ref(1),objetoId=ref('chair'),cantidad=ref(1),posicionId=ref('on'),retoIdx=ref(0),elegida=ref(null),aciertos=ref(new Set());
const objetos=[{id:'chair',uno:'chair',muchos:'chairs',icono:'🪑'},{id:'plant',uno:'plant',muchos:'plants',icono:'🪴'},{id:'book',uno:'book',muchos:'books',icono:'📚'},{id:'apple',uno:'apple',muchos:'apples',icono:'🍎'},{id:'window',uno:'window',muchos:'windows',icono:'🪟'}];
const posiciones=[{id:'in',prep:'in',sujeto:'The keys',objeto:'the drawer',icono:'🔑 🗄️',es:'dentro de'},{id:'on',prep:'on',sujeto:'The book',objeto:'the table',icono:'📕\n🪵',es:'sobre una superficie'},{id:'under',prep:'under',sujeto:'The cat',objeto:'the chair',icono:'🪑\n🐈',es:'debajo de'},{id:'next',prep:'next to',sujeto:'The lamp',objeto:'the sofa',icono:'💡 🛋️',es:'al lado de'},{id:'between',prep:'between',sujeto:'The plant',objeto:'the chair and the table',icono:'🪑 🪴 🪵',es:'entre dos cosas'},{id:'behind',prep:'behind',sujeto:'The bag',objeto:'the door',icono:'🎒 ↤ 🚪',es:'detrás de'},{id:'front',prep:'in front of',sujeto:'The bicycle',objeto:'the house',icono:'🚲 → 🏠',es:'delante de'},{id:'above',prep:'above',sujeto:'The picture',objeto:'the sofa',icono:'🖼️\n🛋️',es:'arriba, sin tocar'}];
const objeto=computed(()=>objetos.find(x=>x.id===objetoId.value)),posicion=computed(()=>posiciones.find(x=>x.id===posicionId.value));
const fraseExistencia=computed(()=>`There ${cantidad.value===1?'is':'are'} ${cantidad.value===1?'a':cantidad.value} ${cantidad.value===1?objeto.value.uno:objeto.value.muchos} in the room.`);
const frasePosicion=computed(()=>`${posicion.value.sujeto} is ${posicion.value.prep} ${posicion.value.objeto}.`);
const meta=computed(()=>props.mode==='existence'?{icono:'🏠',sobre:'QUÉ HAY',titulo:'There is y there are',bajada:'Presentá lo que existe en un lugar según sea singular o plural.',tabs:['Decorá la habitación','Afirmar, negar, preguntar','Reto singular / plural']}:{icono:'📍',sobre:'DÓNDE ESTÁ',titulo:'Preposiciones de ubicación',bajada:'Ubicá personas y objetos con referencias claras y cotidianas.',tabs:['Explorá la habitación','Mapa de posiciones','Reto espacial']});
const retos=computed(()=>props.mode==='existence'?[{i:'🪑',f:'___ a chair by the window.',r:'There is',o:['There is','There are','It has','They are'],a:'A chair es singular: there is.'},{i:'📚',f:'___ three books on the table.',r:'There are',o:['There is','There are','They have','It is'],a:'Three books es plural: there are.'},{i:'☕',f:'___ any coffee left?',r:'Is there',o:['Are there','There is','Is there','It is'],a:'La pregunta singular empieza con Is there…?'},{i:'🪟',f:'___ two windows in the room?',r:'Are there',o:['Is there','Are there','There are','Do there'],a:'La pregunta plural empieza con Are there…?'}]:[{i:'🔑',f:'The keys are ___ the drawer.',r:'in',o:['in','on','at','above'],a:'In significa dentro de un espacio.'},{i:'📕',f:'The book is ___ the table.',r:'on',o:['under','on','between','behind'],a:'On indica contacto con una superficie.'},{i:'🐈',f:'The cat is ___ the chair.',r:'under',o:['above','next to','under','in front of'],a:'Under significa debajo de.'},{i:'🪴',f:'The plant is ___ the chair and the table.',r:'between',o:['behind','between','on','in'],a:'Between ubica algo entre dos referencias.'}]);
const reto=computed(()=>retos.value[retoIdx.value]),correcta=computed(()=>elegida.value===reto.value.r);
function escuchar(t){emit('hablar',t,1)}function responder(o){elegida.value=o;if(o===reto.value.r)aciertos.value=new Set([...aciertos.value,retoIdx.value])}function siguiente(){retoIdx.value=(retoIdx.value+1)%retos.value.length;elegida.value=null}watch(()=>props.mode,()=>{paso.value=1;retoIdx.value=0;elegida.value=null;aciertos.value=new Set()});
</script>

<template><section class="location" :class="`location--${mode}`"><aside class="hero"><span>{{meta.icono}}</span><div><small>ADULTO ESTÁNDAR · {{meta.sobre}}</small><h2>{{meta.titulo}}</h2><p>{{meta.bajada}}</p></div><div class="pin"><b>{{mode==='existence'?'THERE':'WHERE'}}</b><i>→</i><span>{{mode==='existence'?'EXISTS':'PLACE'}}</span></div></aside><nav><button v-for="(tab,i) in meta.tabs" :key="tab" :class="{active:paso===i+1}" @click="paso=i+1"><b>0{{i+1}}</b><span>{{tab}}</span></button></nav>
<main v-if="paso===1 && mode==='existence'"><header><small>THERE IS / ARE 1</small><h3>Decorá la habitación</h3><p>Elegí un objeto y su cantidad. La frase cambia entre singular y plural.</p></header><div class="quantity"><button v-for="n in 3" :key="n" :class="{active:cantidad===n}" @click="cantidad=n">{{n}}</button></div><div class="object-grid"><button v-for="x in objetos" :key="x.id" :class="{active:objetoId===x.id}" @click="objetoId=x.id"><span>{{x.icono}}</span><b>{{cantidad===1?x.uno:x.muchos}}</b></button></div><article class="room"><span v-for="n in cantidad" :key="n">{{objeto.icono}}</span><small>IN THE ROOM</small><strong>{{fraseExistencia}}</strong><button @click="escuchar(fraseExistencia)">🔊 Escuchar</button></article></main>
<main v-else-if="paso===1"><header><small>UBICACIÓN 1</small><h3>Explorá la habitación</h3><p>Tocá una preposición para mover el foco y escuchar una escena.</p></header><div class="prep-grid"><button v-for="x in posiciones" :key="x.id" :class="{active:posicionId===x.id}" @click="posicionId=x.id"><b>{{x.prep}}</b><small>{{x.es}}</small></button></div><article class="scene"><span>{{posicion.icono}}</span><small>{{posicion.prep.toUpperCase()}}</small><strong>{{frasePosicion}}</strong><button @click="escuchar(frasePosicion)">🔊 Escuchar ubicación</button></article></main>
<main v-else-if="paso===2 && mode==='existence'"><header><small>THERE IS / ARE 2</small><h3>Tres formas, una misma idea</h3><p>El verbo pasa al frente para preguntar y recibe not para negar.</p></header><div class="forms"><article><span>✓</span><small>AFIRMACIÓN</small><b>There is a plant.</b><b>There are two plants.</b></article><article><span>−</span><small>NEGACIÓN</small><b>There isn't a plant.</b><b>There aren't any plants.</b></article><article><span>?</span><small>PREGUNTA</small><b>Is there a plant?</b><b>Are there any plants?</b></article></div><aside class="note"><b>There is ≠ It is:</b> <i>there is</i> anuncia que algo existe; <i>it is</i> identifica o describe algo ya mencionado.</aside></main>
<main v-else-if="paso===2"><header><small>UBICACIÓN 2</small><h3>Mapa de posiciones</h3><p>Usá el objeto de referencia como punto de orientación.</p></header><div class="map"><article v-for="x in posiciones" :key="x.id"><span>{{x.icono}}</span><b>{{x.prep}}</b><small>{{x.es}}</small></article></div><aside class="note"><b>Atajo:</b> <i>in</i> = dentro; <i>on</i> = tocando una superficie; <i>at</i> = un punto o lugar específico.</aside></main>
<main v-else><header class="challenge-head"><div><small>{{meta.sobre}} · RETO</small><h3>{{meta.tabs[2]}}</h3><p>Observá cantidad o relación espacial antes de responder.</p></div><b>{{aciertos.size}}/{{retos.length}}</b></header><article class="challenge"><span>{{reto.i}}</span><button @click="escuchar(reto.f.replace('___',reto.r))">{{reto.f}} 🔊</button><div><button v-for="o in reto.o" :key="o" :class="{ok:elegida&&o===reto.r,bad:elegida===o&&o!==reto.r}" @click="responder(o)">{{o}}</button></div><p v-if="elegida"><b>{{correcta?'✓ Bien ubicado':'↻ Mirá la referencia'}}</b> {{reto.a}}</p><button v-if="correcta" class="next" @click="siguiente">Siguiente escena →</button></article></main><button class="practice" :disabled="completado" @click="emit('practicar')">{{completado?'✓ Ejercicios ya acreditados':'Practicar ejercicios del workbook →'}}</button></section></template>

<style scoped>
.location{display:grid;gap:1rem;--accent:#39745e;--soft:#e9f6ef;--warm:#fff3de}.location--location{--accent:#4b6f9d;--soft:#eaf2fb;--warm:#f5edfb}.hero,main{padding:1rem;border:1px solid var(--color-borde);border-radius:var(--radio-panel);background:var(--color-superficie)}.hero{display:grid;grid-template-columns:auto 1fr auto;align-items:center;gap:.8rem;background:linear-gradient(135deg,var(--soft),var(--warm))}.hero>span{font-size:2.7rem}.hero h2,main h3{margin:.15rem 0}.hero p,main header p{margin:.25rem 0;color:var(--color-texto-secundario)}small{font-size:.62rem;font-weight:900;letter-spacing:.08em;color:var(--accent)}.pin{display:flex;gap:.35rem;padding:.6rem;border:1px dashed var(--accent);border-radius:10px;color:var(--accent);font-size:.64rem}nav{display:grid;grid-template-columns:repeat(3,1fr);gap:.5rem}nav button{display:flex;gap:.5rem;padding:.7rem;border:1px solid var(--color-borde);border-radius:12px;background:var(--color-superficie);text-align:left}nav button b{color:var(--accent)}nav button.active,.quantity button.active,.object-grid button.active,.prep-grid button.active{border-color:var(--accent)!important;background:var(--soft)!important}.quantity{display:flex;justify-content:center;gap:.5rem}.quantity button{width:44px;height:44px;border:1px solid var(--color-borde);border-radius:50%;background:var(--color-superficie);font-weight:900}.object-grid{display:grid;grid-template-columns:repeat(5,1fr);gap:.45rem;margin:.7rem 0}.object-grid button{display:flex;flex-direction:column;align-items:center;padding:.6rem;border:1px solid var(--color-borde);border-radius:11px;background:var(--color-superficie)}.object-grid span{font-size:1.7rem}.room,.scene{display:flex;flex-direction:column;align-items:center;min-height:190px;justify-content:center;padding:1rem;border-radius:16px;background:linear-gradient(145deg,var(--soft),var(--warm));text-align:center}.room>span{display:inline;font-size:2.2rem}.room strong,.scene strong{font:italic 1.15rem Georgia}.room button,.scene button{margin-top:.5rem;padding:.5rem .7rem;border:0;border-radius:var(--radio-boton);background:var(--accent);color:#fff}.prep-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:.45rem}.prep-grid button{display:flex;flex-direction:column;padding:.6rem;border:1px solid var(--color-borde);border-radius:10px;background:var(--color-superficie)}.scene{margin-top:.8rem}.scene>span{white-space:pre-line;font-size:2.8rem;line-height:1.2}.forms{display:grid;grid-template-columns:repeat(3,1fr);gap:.6rem}.forms article{display:flex;flex-direction:column;padding:.8rem;border:1px solid var(--color-borde);border-radius:13px;background:var(--color-superficie)}.forms article>span{font-size:1.5rem}.forms article>b{font:italic .78rem Georgia}.map{display:grid;grid-template-columns:repeat(4,1fr);gap:.5rem}.map article{display:flex;flex-direction:column;align-items:center;padding:.7rem;border:1px solid var(--color-borde);border-radius:11px;text-align:center}.map article>span{white-space:pre-line;font-size:1.5rem;text-align:center}.map article>b{color:var(--accent)}.note{margin-top:.7rem;padding:.7rem;border-left:4px solid var(--accent);border-radius:8px;background:var(--soft);font-size:.75rem}.challenge-head{display:flex;justify-content:space-between}.challenge-head>b{display:grid;place-items:center;width:48px;height:48px;border-radius:50%;background:var(--soft);color:var(--accent)}.challenge{max-width:650px;margin:auto;padding:1rem;border-radius:16px;background:linear-gradient(145deg,var(--soft),var(--warm));text-align:center}.challenge>span{font-size:2.7rem}.challenge>button{display:block;margin:.4rem auto;border:0;background:transparent;font:italic 1.1rem Georgia}.challenge>div{display:grid;grid-template-columns:1fr 1fr;gap:.4rem}.challenge>div button{padding:.6rem;border:1px solid var(--color-borde);border-radius:9px;background:var(--color-superficie)}.challenge .ok{border-color:var(--color-verde);background:var(--color-verde-suave)}.challenge .bad{border-color:var(--color-rojo);background:var(--color-rojo-suave)}.next{padding:.55rem .8rem!important;background:var(--accent)!important;color:#fff!important}.practice{width:100%;padding:.8rem;border:0;border-radius:var(--radio-boton);background:var(--accent);color:#fff;font-weight:800}.practice:disabled{background:var(--color-verde)}
@media(max-width:650px){.hero{grid-template-columns:auto 1fr}.pin{grid-column:1/-1;justify-content:center}nav,.forms,.challenge>div{grid-template-columns:1fr}.object-grid{grid-template-columns:repeat(3,1fr)}.prep-grid,.map{grid-template-columns:1fr 1fr}}@media(max-width:400px){.object-grid{grid-template-columns:1fr 1fr}.prep-grid,.map{grid-template-columns:1fr}}
</style>
